package com.example.game.ai.director.modules

import org.json.JSONObject

/**
 * Validates JSON schema & ASCII grid generated by Ollama for 12x12 room components.
 */
object OllamaRoomSchemaValidator {
    
    val VALID_HAZARD_MUTATORS = setOf("BARREL_OVERLOAD", "CRYO_FOG", "HIGH_VOLTAGE_GRID", "BLOOD_MOON_SWARM")
    val VALID_VENDOR_TAGS = setOf("MARCUS_LEGENDARY_ARMS", "ZED_CRYO_SHIELDS", "TORGUE_BLAST_ORDNANCE")
    val VALID_GRID_CHARS = setOf('#', '.', 'W', 'D', 'V', 'P', 'B', 'U')

    fun validateOllamaResponse(rawJson: String): Boolean {
        try {
            val obj = JSONObject(rawJson)
            
            // Check required fields
            if (!obj.has("componentId") || 
                !obj.has("sectorCodename") || 
                !obj.has("hazardMutator") || 
                !obj.has("featuredVendorTag") || 
                !obj.has("rows")) {
                return false
            }

            // Check field constraints
            if (obj.getString("hazardMutator") !in VALID_HAZARD_MUTATORS) return false
            if (obj.getString("featuredVendorTag") !in VALID_VENDOR_TAGS) return false

            val rowsArr = obj.optJSONArray("rows") ?: return false
            if (rowsArr.length() != 12) return false

            val rows = mutableListOf<String>()
            for (i in 0 until 12) {
                val row = rowsArr.optString(i) ?: return false
                if (row.length != 12) return false
                // Check valid characters
                if (row.any { it !in VALID_GRID_CHARS }) return false
                rows.add(row)
            }
            
            // Verify topological reachability (BFS)
            return verifySolvability(rows)
            
        } catch (e: Exception) {
            return false
        }
    }

    /**
     * Checks if all walkable floor tiles ('.') form a single connected component.
     */
    fun verifySolvability(rows: List<String>): Boolean {
        var startX = -1
        var startY = -1
        var totalWalkable = 0

        for (y in 0 until 12) {
            for (x in 0 until 12) {
                if (rows[y][x] == '.') {
                    totalWalkable++
                    if (startX == -1) {
                        startX = x
                        startY = y
                    }
                }
            }
        }

        // If no walkable tiles, it's technically fully connected (0/0) or trivially unsolvable, 
        // but typically a room with 0 walkable tiles is invalid for gameplay.
        if (totalWalkable == 0) return false

        val visited = Array(12) { BooleanArray(12) }
        val queue = ArrayDeque<Pair<Int, Int>>()
        
        queue.add(startX to startY)
        visited[startY][startX] = true
        var reachableWalkable = 1

        val dirs = listOf(
            0 to -1, // Up
            0 to 1,  // Down
            -1 to 0, // Left
            1 to 0   // Right
        )

        while (queue.isNotEmpty()) {
            val (cx, cy) = queue.removeFirst()

            for ((dx, dy) in dirs) {
                val nx = cx + dx
                val ny = cy + dy
                
                if (nx in 0 until 12 && ny in 0 until 12) {
                    if (!visited[ny][nx] && rows[ny][nx] == '.') {
                        visited[ny][nx] = true
                        queue.add(nx to ny)
                        reachableWalkable++
                    }
                }
            }
        }

        return reachableWalkable == totalWalkable
    }
}
